            var pcgJob = new PcgBsrJobFloat { A = A, M = M, b = b, x = xPcg, r = rPcg, p = pPcg, Ap = ApPcg, z = zPcg, K = K };
            var pcgStat = Bench.Time(() => pcgJob.Run());
